#include <stdio.h>
#include <string.h>

int main(void)
{
    char line[] = "a::b:c";
    char *save;
    char *t = strtok_r(line, ":", &save);

    while (t != NULL) {
        printf("[%s]", t);
        t = strtok_r(NULL, ":", &save);
    }
    printf("\n");
    return 0;
}

